def is_valid_timestamp(item: dict) -> bool:
    """Check if item has a valid ISO format timestamp."""
    if 'timestamp' not in item:
        return True  # timestamp is optional

    if not isinstance(item['timestamp'], str):
        return False

    try:
        datetime.fromisoformat(item['timestamp'])
        return True
    except ValueError:
        return False


def process_data(data: list) -> dict:
    """Process a list of data items, separating valid and invalid entries."""
    result = {'valid': [], 'invalid': [], 'errors': []}

    for item in data:
        # Early continue for items missing required fields
        if not ('id' in item and 'value' in item):
            result['invalid'].append(item)
            result['errors'].append("Missing required fields")
            continue

        # Validate each aspect separately
        if not is_valid_id(item):
            result['invalid'].append(item)
            result['errors'].append(f"Invalid ID: {item.get('id')}")
            continue

        if not is_valid_value(item):
            result['invalid'].append(item)
            result['errors'].append(f"Invalid value: {item.get('value')}")
            continue

        if not is_valid_timestamp(item):
            result['invalid'].append(item)
            error = f"Invalid timestamp: {item.get('timestamp')}"
            result['errors'].append(error)
            continue

        # If all validations passed
        result['valid'].append(item)

    return result
